SELECT FROM alarm_dispatch_rule
del_flag = 0
AND name LIKE CONCAT('%', #{where.name}, '%')
AND event_type = #{where.eventType}
AND is_enabled = #{where.isEnabled}
ORDER BY create_time DESC

