UPDATE alarm_dispatch_rule
name = #{name}, event_type = #{eventType}, alarm_levels = #{alarmLevels}, channels = #{channels}, is_enabled = #{isEnabled}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime}
